function minuteFormData(){return {meetingNo:$('bmNo').value.trim(),title:$('bmKind').value,date:$('bmDate').value,time:$('bmTime').value,place:$('bmPlace').value.trim(),chair:$('bmChair').value.trim(),secretary:$('bmSecretary').value.trim(),attendees:$('bmAttendees').value.trim(),absentees:$('bmAbsentees').value.trim(),agenda:$('bmAgenda').value.trim(),discussion:$('bmDiscussion').value.trim(),decisions:$('bmDecisions').value.trim(),vote:$('bmVote').value.trim(),endTime:$('bmEndTime').value,status:$('bmStatus').value}}
function saveBoardMinute(ev){
 ev.preventDefault();if(typeof boardMinutes==='undefined')return alert('تعذر الوصول إلى سجل المحاضر الحالي.');
 const data=minuteFormData();if(!data.date||!data.agenda||!data.decisions)return alert('أدخل التاريخ وجدول الأعمال والقرارات.');
 const id=$('bmId').value||uid(),old=boardMinutes.find(x=>x.id===id);
 const row={...(old||{}),id,...data,notes:data.agenda+' | المناقشات: '+data.discussion+' | القرارات: '+data.decisions,createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),createdBy:old?.createdBy||who(),updatedBy:who()};
 if(old)boardMinutes=boardMinutes.map(x=>x.id===id?row:x);else boardMinutes.unshift(row);
 const a=arr('archive'),ai=a.findIndex(x=>x.documentId===id);const archiveRow={...(ai>=0?a[ai]:{}),id:ai>=0?a[ai].id:uid(),documentId:id,serial:data.meetingNo,title:'محضر مجلس إدارة – '+data.title,date:data.date,category:'محاضر مجلس الإدارة',status:data.status,createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};
 if(ai>=0)a[ai]=archiveRow;else a.unshift(archiveRow);
 saveData();$('bmId').value=id;$('bmSaveBtn').textContent='حفظ التعديلات';renderBoardMinuteList();toast(old?'تم تحديث المحضر وحفظ التعديلات.':'تم حفظ المحضر في سجل الجمعية والأرشيف.');
}
function editMinute(id){const x=boardMinutes.find(y=>y.id===id);if(!x)return;const map={bmId:'id',bmNo:'meetingNo',bmDate:'date',bmKind:'title',bmTime:'time',bmPlace:'place',bmChair:'chair',bmSecretary:'secretary',bmAttendees:'attendees',bmAbsentees:'absentees',bmAgenda:'agenda',bmDiscussion:'discussion',bmDecisions:'decisions',bmVote:'vote',bmEndTime:'endTime',bmStatus:'status'};Object.entries(map).forEach(([el,k])=>{if($(el))$(el).value=x[k]??''});$('bmSaveBtn').textContent='حفظ التعديلات';$('jkhBoardMinuteForm').scrollIntoView({behavior:'smooth',block:'start'});}
function resetMinuteForm(){$('jkhBoardMinuteForm').reset();$('bmId').value='';$('bmDate').value=today();$('bmPlace').value='مقر جمعية الخير للجميع – كوم أبو خلاد – مركز ناصر – بني سويف';$('bmNo').value=String((typeof boardMinutes!=='undefined'?boardMinutes.length:0)+1).padStart(4,'0');$('bmSaveBtn').textContent='حفظ المحضر';}
function renderBoardMinuteList(){
 const box=$('jkhBoardMinuteList');if(!box||typeof boardMinutes==='undefined')return;
 const rows=boardMinutes.filter(x=>x.agenda||x.decisions||x.fileName).map(x=>`<div class="fin-doc"><div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><b>محضر رقم ${esc(x.meetingNo||'—')} – ${esc(x.title||'اجتماع مجلس الإدارة')}</b><span class="fin-status">${esc(x.status||'مسودة')}</span></div><div class="fin-muted">${esc(x.date||'')} • ${esc(x.place||'')}</div><div class="fin-actions"><button class="secondary" onclick="JKHFin.editMinute('${x.id}')">تعديل</button><button class="secondary" onclick="JKHFin.printMinute('${x.id}')">معاينة / طباعة / PDF</button></div></div>`).join('');
 box.innerHTML='<h3>المحاضر المحفوظة</h3>'+(rows||'<div class="empty">لا توجد محاضر منشأة بعد.</div>');
}
